mapper.update:
/* DailyLoginMapper.updateDailyUserPwdReset */
UPDATE TB_DAILY_USER
SET PWD_LOCK_YN            = 'N'
    , PWD_FAIL_CNT          = 0
    , PWD_LOCK_EXPIRE_DTIME = NULL
    , UPDATE_NO             = 'SYSTEM'
    , UPDATE_DATE           = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND USER_CD  = #{userCd}

/* DailyLoginMapper.updateDailyUserLastLoginDtime */
UPDATE TB_DAILY_USER
SET LAST_LOGIN_DTIME = NOW()
    , UPDATE_NO      = 'SYSTEM'
    , UPDATE_DATE    = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND USER_CD  = #{userCd}

/* DailyLoginMapper.revokeDailyActiveToken */
UPDATE TB_AUTH_TOKEN
SET REVOKED_YN    = 'Y',
    REVOKED_DTIME = NOW(),
    UPDATE_NO     = #{userCd},
    UPDATE_DATE   = NOW()
WHERE CMPNY_CD    = #{cmpnyCd}
  AND USER_CD     = #{userCd}
  AND CLIENT_TYPE = #{clientType}
  AND REVOKED_YN  = 'N'
  AND EXPIRE_DTIME > NOW()

mapper.insert:
/* DailyLoginMapper.insertDailyAuthToken */
INSERT INTO TB_AUTH_TOKEN (
    CMPNY_CD
    , USER_CD
    , TOKEN_ID
    , CLIENT_TYPE
    , REFRESH_TOKEN_HASH
    , ISSUED_DTIME
    , EXPIRE_DTIME
    , REVOKED_YN
    , REVOKED_DTIME
    , INSERT_NO
    , INSERT_DATE
) VALUES (
    #{cmpnyCd}
    , #{userCd}
    , #{tokenId}
    , #{clientType}
    , #{refreshTokenHash}
    , NOW()
    , DATE_ADD(NOW(), INTERVAL #{expireDtime} DAY)
    , 'N'
    , NULL
    , #{userCd}
    , NOW()
)
